1	package com.example.starter.baggage;
2	
3	import java.util.ArrayList;
4	import java.util.HashSet;
5	import java.util.List;
6	import java.util.Set;
7	
8	import com.fasterxml.jackson.databind.ObjectMapper;
9	import org.springframework.jdbc.core.JdbcTemplate;
10	import org.springframework.jdbc.core.RowMapper;
11	import org.springframework.stereotype.Service;
12	
13	import com.example.starter.baggage.BaggageDtos.ArriveRequest;
14	import com.example.starter.baggage.BaggageDtos.ArriveResponse;
15	import com.example.starter.baggage.BaggageDtos.BagResponse;
16	import com.example.starter.baggage.BaggageDtos.ItineraryItem;
17	import com.example.starter.baggage.BaggageDtos.LegResponse;
18	import com.example.starter.baggage.BaggageDtos.LoadRequest;
19	import com.example.starter.baggage.BaggageDtos.LoadResponse;
20	import com.example.starter.baggage.BaggageDtos.ManifestResponse;
21	import com.example.starter.baggage.BaggageDtos.RegisterBagRequest;
22	import com.example.starter.baggage.BaggageDtos.RegisterLegRequest;
23	import com.example.starter.baggage.BaggageDtos.SealRequest;
24	import com.example.starter.baggage.BaggageDtos.SealResponse;
25	
26	/**
27	 * 联程行李装载交接核心业务：航段/行李登记、批量装载、封舱、到达确认与查询。
28	 * 所有写操作经 {@link IdempotencyService} 去重，业务变更与去重记录原子提交；
29	 * 航段行级锁（SELECT ... FOR UPDATE）保证装载与封舱并发时以版本决定唯一先后，
30	 * load_record 以 bag_tag 为主键保证同件行李不会进入两个清单。
31	 */
32	@Service
33	public class BaggageService {
34	
35	    private static final String LEG_OPEN = "OPEN";
36	    private static final String LEG_SEALED = "SEALED";
37	    private static final String LEG_ARRIVED = "ARRIVED";
38	    private static final String BAG_IN_TRANSIT = "IN_TRANSIT";
39	    private static final String BAG_DELIVERED = "DELIVERED";
40	
41	    private static final RowMapper<LegRow> LEG_MAPPER = (rs, rowNum) -> new LegRow(
42	            rs.getString("leg_id"), rs.getString("origin"), rs.getString("destination"),
43	            rs.getString("status"), rs.getInt("version"), rs.getString("sealed_manifest"));
44	
45	    private static final RowMapper<BagRow> BAG_MAPPER = (rs, rowNum) -> new BagRow(
46	            rs.getString("bag_tag"), rs.getString("current_location"),
47	            rs.getInt("next_leg_index"), rs.getString("status"), rs.getString("loaded_leg_id"));
48	
49	    private static final RowMapper<ItineraryItem> ITINERARY_MAPPER = (rs, rowNum) -> new ItineraryItem(
50	            rs.getInt("seq"), rs.getString("leg_id"), rs.getString("origin"), rs.getString("destination"));
51	
52	    private final JdbcTemplate jdbcTemplate;
53	    private final IdempotencyService idempotencyService;
54	    private final ObjectMapper objectMapper;
55	
56	    public BaggageService(JdbcTemplate jdbcTemplate,
57	                          IdempotencyService idempotencyService,
58	                          ObjectMapper objectMapper) {
59	        this.jdbcTemplate = jdbcTemplate;
60	        this.idempotencyService = idempotencyService;
61	        this.objectMapper = objectMapper;
62	    }
63	
64	    /** 登记航段：legId 唯一，初始状态 OPEN、版本 1。 */
65	    public LegResponse registerLeg(RegisterLegRequest request) {
66	        return idempotencyService.execute(request.requestId(), "REGISTER_LEG", 201,
67	                request, LegResponse.class, () -> doRegisterLeg(request));
68	    }
69	
70	    /** 登记行李：1~5 个无重复有序航段，相邻航段首尾站衔接，初始位于首段始发站。 */
71	    public BagResponse registerBag(RegisterBagRequest request) {
72	        return idempotencyService.execute(request.requestId(), "REGISTER_BAG", 201,
73	                request, BagResponse.class, () -> doRegisterBag(request));
74	    }
75	
76	    /** 批量装载：整批原子，任一行李不满足则 422 且无一件移动。 */
77	    public LoadResponse load(String legId, LoadRequest request) {
78	        LoadPayload payload = new LoadPayload(legId, request.expectedVersion(), sortedCopy(request.bagTags()));
79	        return idempotencyService.execute(request.requestId(), "LOAD", 200,
80	                payload, LoadResponse.class, () -> doLoad(legId, request));
81	    }
82	
83	    /** 封舱：校验版本，保存只读装载清单并转 SEALED；空清单也可封舱。 */
84	    public SealResponse seal(String legId, SealRequest request) {
85	        SealPayload payload = new SealPayload(legId, request.expectedVersion());
86	        return idempotencyService.execute(request.requestId(), "SEAL", 200,
87	                payload, SealResponse.class, () -> doSeal(legId, request));
88	    }
89	
90	    /** 到达确认：实际袋号集合须与封舱清单完全一致，匹配则原子转 ARRIVED 并推进各行李。 */
91	    public ArriveResponse arrive(String legId, ArriveRequest request) {
92	        ArrivePayload payload = new ArrivePayload(legId, sortedCopy(request.bagTags()));
93	        return idempotencyService.execute(request.requestId(), "ARRIVE", 200,
94	                payload, ArriveResponse.class, () -> doArrive(legId, request));
95	    }
96	
97	    /** 行李轨迹查询。 */
98	    public BagResponse getBagTrace(String bagTag) {
99	        BagRow bag = findBag(bagTag);
100	        if (bag == null) {
101	            throw ApiException.notFound("行李不存在: " + bagTag);
102	        }
103	        return toBagResponse(bag);
104	    }
105	
106	    /** 封舱清单查询：未封舱时返回空清单。 */
107	    public ManifestResponse getManifest(String legId) {
108	        LegRow leg = findLeg(legId);
109	        if (leg == null) {
110	            throw ApiException.notFound("航段不存在: " + legId);
111	        }
112	        List<String> manifest = leg.sealedManifest() == null ? List.of() : readJsonList(leg.sealedManifest());
113	        return new ManifestResponse(leg.legId(), leg.status(), leg.version(), manifest);
114	    }
115	
116	    private LegResponse doRegisterLeg(RegisterLegRequest request) {
117	        if (findLeg(request.legId()) != null) {
118	            throw ApiException.conflict("航段已存在: " + request.legId());
119	        }
120	        jdbcTemplate.update(
121	                "INSERT INTO leg (leg_id, origin, destination, status, version) VALUES (?, ?, ?, ?, 1)",
122	                request.legId(), request.origin(), request.destination(), LEG_OPEN);
123	        return new LegResponse(request.legId(), request.origin(), request.destination(), LEG_OPEN, 1);
124	    }
125	
126	    private BagResponse doRegisterBag(RegisterBagRequest request) {
127	        List<String> legIds = request.legIds();
128	        if (new HashSet<>(legIds).size() != legIds.size()) {
129	            throw ApiException.unprocessable("行程航段不得重复");
130	        }
131	        if (findBag(request.bagTag()) != null) {
132	            throw ApiException.conflict("行李已存在: " + request.bagTag());
133	        }
134	        List<LegRow> legs = new ArrayList<>();
135	        for (String legId : legIds) {
136	            LegRow leg = findLeg(legId);
137	            if (leg == null) {
138	                throw ApiException.unprocessable("行程引用的航段不存在: " + legId);
139	            }
140	            legs.add(leg);
141	        }
142	        for (int i = 0; i + 1 < legs.size(); i++) {
143	            if (!legs.get(i).destination().equals(legs.get(i + 1).origin())) {
144	                throw ApiException.unprocessable(
145	                        "相邻航段首尾站必须衔接: " + legs.get(i).legId() + " -> " + legs.get(i + 1).legId());
146	            }
147	        }
148	        jdbcTemplate.update(
149	                "INSERT INTO bag (bag_tag, current_location, next_leg_index, status) VALUES (?, ?, 0, ?)",
150	                request.bagTag(), legs.get(0).origin(), BAG_IN_TRANSIT);
151	        for (int i = 0; i < legs.size(); i++) {
152	            LegRow leg = legs.get(i);
153	            jdbcTemplate.update(
154	                    "INSERT INTO bag_itinerary (bag_tag, seq, leg_id, origin, destination) VALUES (?, ?, ?, ?, ?)",
155	                    request.bagTag(), i, leg.legId(), leg.origin(), leg.destination());
156	        }
157	        return new BagResponse(request.bagTag(), legs.get(0).origin(), 0, BAG_IN_TRANSIT, null,
158	                toItinerary(request.bagTag()));
159	    }
160	
161	    private LoadResponse doLoad(String legId, LoadRequest request) {
162	        LegRow leg = lockLeg(legId);
163	        checkVersion(leg, request.expectedVersion());
164	        if (!LEG_OPEN.equals(leg.status())) {
165	            throw ApiException.unprocessable("航段状态为 " + leg.status() + "，禁止装载");
166	        }
167	        List<String> bagTags = request.bagTags();
168	        if (new HashSet<>(bagTags).size() != bagTags.size()) {
169	            throw ApiException.unprocessable("批量装载的 bagTag 不得重复");
170	        }
171	        List<String> sorted = sortedCopy(bagTags);
172	        List<BagRow> bags = new ArrayList<>();
173	        for (String bagTag : sorted) {
174	            BagRow bag = lockBag(bagTag);
175	            if (bag == null) {
176	                throw ApiException.unprocessable("行李不存在: " + bagTag);
177	            }
178	            validateLoadable(bag, leg);
179	            bags.add(bag);
180	        }
181	        for (BagRow bag : bags) {
182	            jdbcTemplate.update("INSERT INTO load_record (bag_tag, leg_id) VALUES (?, ?)", bag.bagTag(), legId);
183	            jdbcTemplate.update("UPDATE bag SET loaded_leg_id = ? WHERE bag_tag = ?", legId, bag.bagTag());
184	        }
185	        int newVersion = leg.version() + 1;
186	        jdbcTemplate.update("UPDATE leg SET version = ? WHERE leg_id = ?", newVersion, legId);
187	        return new LoadResponse(legId, LEG_OPEN, newVersion, sorted);
188	    }
189	
190	    private SealResponse doSeal(String legId, SealRequest request) {
191	        LegRow leg = lockLeg(legId);
192	        checkVersion(leg, request.expectedVersion());
193	        if (!LEG_OPEN.equals(leg.status())) {
194	            throw ApiException.unprocessable("航段状态为 " + leg.status() + "，禁止封舱");
195	        }
196	        List<String> manifest = jdbcTemplate.queryForList(
197	                "SELECT bag_tag FROM load_record WHERE leg_id = ? ORDER BY bag_tag", String.class, legId);
198	        int newVersion = leg.version() + 1;
199	        jdbcTemplate.update("UPDATE leg SET status = ?, version = ?, sealed_manifest = ? WHERE leg_id = ?",
200	                LEG_SEALED, newVersion, writeJson(manifest), legId);
201	        return new SealResponse(legId, LEG_SEALED, newVersion, manifest);
202	    }
203	
204	    private ArriveResponse doArrive(String legId, ArriveRequest request) {
205	        LegRow leg = lockLeg(legId);
206	        if (!LEG_SEALED.equals(leg.status())) {
207	            throw ApiException.unprocessable("航段状态为 " + leg.status() + "，禁止到达确认");
208	        }
209	        List<String> manifest = readJsonList(leg.sealedManifest());
210	        List<String> actual = request.bagTags();
211	        Set<String> actualSet = new HashSet<>(actual);
212	        if (actualSet.size() != actual.size() || !actualSet.equals(new HashSet<>(manifest))) {
213	            throw ApiException.unprocessable("实际袋号集合与封舱清单不一致");
214	        }
215	        for (String bagTag : manifest) {
216	            BagRow bag = lockBag(bagTag);
217	            int nextIndex = bag.nextLegIndex() + 1;
218	            int total = itineraryCount(bagTag);
219	            String status = nextIndex >= total ? BAG_DELIVERED : BAG_IN_TRANSIT;
220	            jdbcTemplate.update(
221	                    "UPDATE bag SET current_location = ?, next_leg_index = ?, status = ?, loaded_leg_id = NULL"
222	                            + " WHERE bag_tag = ?",
223	                    leg.destination(), nextIndex, status, bagTag);
224	        }
225	        jdbcTemplate.update("DELETE FROM load_record WHERE leg_id = ?", legId);
226	        int newVersion = leg.version() + 1;
227	        jdbcTemplate.update("UPDATE leg SET status = ?, version = ? WHERE leg_id = ?",
228	                LEG_ARRIVED, newVersion, legId);
229	        return new ArriveResponse(legId, LEG_ARRIVED, newVersion, manifest);
230	    }
231	
232	    private void validateLoadable(BagRow bag, LegRow leg) {
233	        if (bag.loadedLegId() != null) {
234	            throw ApiException.unprocessable("行李 " + bag.bagTag() + " 已装载到航段 " + bag.loadedLegId());
235	        }
236	        ItineraryItem next = nextItinerary(bag.bagTag(), bag.nextLegIndex());
237	        if (next == null) {
238	            throw ApiException.unprocessable("行李 " + bag.bagTag() + " 已完成全部行程");
239	        }
240	        if (!next.legId().equals(leg.legId())) {
241	            throw ApiException.unprocessable(
242	                    "行李 " + bag.bagTag() + " 当前待乘航段为 " + next.legId() + "，不能装载到 " + leg.legId());
243	        }
244	        if (!bag.currentLocation().equals(leg.origin())) {
245	            throw ApiException.unprocessable("行李 " + bag.bagTag() + " 不在航段始发站 " + leg.origin());
246	        }
247	    }
248	
249	    private void checkVersion(LegRow leg, int expectedVersion) {
250	        if (leg.version() != expectedVersion) {
251	            throw ApiException.conflict(
252	                    "航段版本冲突: 期望 " + expectedVersion + "，当前 " + leg.version());
253	        }
254	    }
255	
256	    private LegRow findLeg(String legId) {
257	        List<LegRow> rows = jdbcTemplate.query(
258	                "SELECT leg_id, origin, destination, status, version, sealed_manifest FROM leg WHERE leg_id = ?",
259	                LEG_MAPPER, legId);
260	        return rows.isEmpty() ? null : rows.get(0);
261	    }
262	
263	    private LegRow lockLeg(String legId) {
264	        List<LegRow> rows = jdbcTemplate.query(
265	                "SELECT leg_id, origin, destination, status, version, sealed_manifest FROM leg"
266	                        + " WHERE leg_id = ? FOR UPDATE",
267	                LEG_MAPPER, legId);
268	        if (rows.isEmpty()) {
269	            throw ApiException.notFound("航段不存在: " + legId);
270	        }
271	        return rows.get(0);
272	    }
273	
274	    private BagRow findBag(String bagTag) {
275	        List<BagRow> rows = jdbcTemplate.query(
276	                "SELECT bag_tag, current_location, next_leg_index, status, loaded_leg_id FROM bag WHERE bag_tag = ?",
277	                BAG_MAPPER, bagTag);
278	        return rows.isEmpty() ? null : rows.get(0);
279	    }
280	
281	    private BagRow lockBag(String bagTag) {
282	        List<BagRow> rows = jdbcTemplate.query(
283	                "SELECT bag_tag, current_location, next_leg_index, status, loaded_leg_id FROM bag"
284	                        + " WHERE bag_tag = ? FOR UPDATE",
285	                BAG_MAPPER, bagTag);
286	        return rows.isEmpty() ? null : rows.get(0);
287	    }
288	
289	    private ItineraryItem nextItinerary(String bagTag, int nextLegIndex) {
290	        List<ItineraryItem> rows = jdbcTemplate.query(
291	                "SELECT seq, leg_id, origin, destination FROM bag_itinerary WHERE bag_tag = ? AND seq = ?",
292	                ITINERARY_MAPPER, bagTag, nextLegIndex);
293	        return rows.isEmpty() ? null : rows.get(0);
294	    }
295	
296	    private int itineraryCount(String bagTag) {
297	        Integer count = jdbcTemplate.queryForObject(
298	                "SELECT COUNT(*) FROM bag_itinerary WHERE bag_tag = ?", Integer.class, bagTag);
299	        return count == null ? 0 : count;
300	    }
301	
302	    private List<ItineraryItem> toItinerary(String bagTag) {
303	        return jdbcTemplate.query(
304	                "SELECT seq, leg_id, origin, destination FROM bag_itinerary WHERE bag_tag = ? ORDER BY seq",
305	                ITINERARY_MAPPER, bagTag);
306	    }
307	
308	    private BagResponse toBagResponse(BagRow bag) {
309	        return new BagResponse(bag.bagTag(), bag.currentLocation(), bag.nextLegIndex(),
310	                bag.status(), bag.loadedLegId(), toItinerary(bag.bagTag()));
311	    }
312	
313	    private static List<String> sortedCopy(List<String> values) {
314	        return values.stream().sorted().toList();
315	    }
316	
317	    private String writeJson(List<String> values) {
318	        try {
319	            return objectMapper.writeValueAsString(values);
320	        } catch (Exception ex) {
321	            throw new IllegalStateException("清单序列化失败", ex);
322	        }
323	    }
324	
325	    private List<String> readJsonList(String json) {
326	        try {
327	            return objectMapper.readValue(json,
328	                    objectMapper.getTypeFactory().constructCollectionType(List.class, String.class));
329	        } catch (Exception ex) {
330	            throw new IllegalStateException("清单反序列化失败", ex);
331	        }
332	    }
333	
334	    private record LegRow(String legId, String origin, String destination,
335	                          String status, int version, String sealedManifest) {
336	    }
337	
338	    private record BagRow(String bagTag, String currentLocation, int nextLegIndex,
339	                          String status, String loadedLegId) {
340	    }
341	
342	    /** 装载幂等摘要参数：bagTags 已排序，顺序差异不视为异参。 */
343	    private record LoadPayload(String legId, int expectedVersion, List<String> bagTags) {
344	    }
345	
346	    /** 封舱幂等摘要参数。 */
347	    private record SealPayload(String legId, int expectedVersion) {
348	    }
349	
350	    /** 到达确认幂等摘要参数：bagTags 已排序，顺序差异不视为异参。 */
351	    private record ArrivePayload(String legId, List<String> bagTags) {
352	    }
353	}
