        // 再装 BAG2：必须按 35 计合计 55 > 40，整批 422，BAG2 不动
        load("LEG1", 2, List.of("BAG2")).andExpect(status().isUnprocessableEntity());
        mockMvc.perform(get("/api/bags/BAG2/trace"))
