                "SELECT overweight_active FROM bag WHERE bag_tag = 'BAG1'", Boolean.class);
        Integer activeAlerts = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM overweight_alert WHERE bag_tag = 'BAG1' AND status = 'ACTIVE'",
